fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    
    // Create a vector with capacity for 3n elements
    let mut result = Vec::with_capacity(3 * n);
    
    // Interleave the elements
    for i in 0..n {
        result.push(s1[i]);
        result.push(s2[i]);
        result.push(s3[i]);
    }
    
    result
}